// Make a ball that grows in size when we put our mouse over it, and then shrinks when we move our mouse away.

// Solution

let width = 750;
let height = 750;

let positionX = 200;
let positionY = 200;

let originalR = 110;
let biggerR = 200;

let svg = d3
	.select("body")
	.append("svg")
	.attr("width", width)
	.attr("height", height);

let circle = svg
	.append("circle")
	.attr("fill", "red")
	.attr("cx", positionX)
	.attr("cy", positionY)
	.attr("r", originalR);

circle.on("mouseover", () => {
	circle.transition().attr("r", biggerR);
});

circle.on("mouseout", () => {
	circle.transition().attr("r", originalR);
});

