// Draw a rainbow with a D3 arcs that fill in from outside-in with a staggered animation!

// Solution

let width = 800;
let height = 450;

let svg = d3
  .select("body")
  .append("svg")
  .attr("width", width)
  .attr("height", height)
  .append("g")
  .attr("transform", "translate(300,300)");

let innerRadius = 300;
let outerRadius = 280;

const arcGenerator = d3.arc();

let red = arcGenerator({
  innerRadius: innerRadius,
  outerRadius: outerRadius,
  startAngle: degreesToRadians(-60),
  endAngle: degreesToRadians(60)
});

innerRadius -= 20;
outerRadius -= 20;

let orange = arcGenerator({
  innerRadius: innerRadius,
  outerRadius: outerRadius,
  startAngle: degreesToRadians(-60),
  endAngle: degreesToRadians(60)
});

innerRadius -= 20;
outerRadius -= 20;

let yellow = arcGenerator({
  innerRadius: innerRadius,
  outerRadius: outerRadius,
  startAngle: degreesToRadians(-60),
  endAngle: degreesToRadians(60)
});

innerRadius -= 20;
outerRadius -= 20;

let green = arcGenerator({
  innerRadius: innerRadius,
  outerRadius: outerRadius,
  startAngle: degreesToRadians(-60),
  endAngle: degreesToRadians(60)
});

innerRadius -= 20;
outerRadius -= 20;

let blue = arcGenerator({
  innerRadius: innerRadius,
  outerRadius: outerRadius,
  startAngle: degreesToRadians(-60),
  endAngle: degreesToRadians(60)
});

innerRadius -= 20;
outerRadius -= 20;

let violet = arcGenerator({
  innerRadius: innerRadius,
  outerRadius: outerRadius,
  startAngle: degreesToRadians(-60),
  endAngle: degreesToRadians(60)
});

let delay = 200;
svg
  .append("path")
  .transition()
  .delay(delay)
  .attr("d", red)
  .attr("fill", "red")
  .duration(150);
delay += 200;

svg
  .append("path")
  .transition()
  .delay(delay)
  .attr("d", orange)
  .attr("fill", "orange")
  .duration(150);
delay += 200;

svg
  .append("path")
  .transition()
  .delay(delay)
  .attr("d", yellow)
  .attr("fill", "yellow")
  .duration(150);
delay += 200;

svg
  .append("path")
  .transition()
  .delay(delay)
  .attr("d", green)
  .attr("fill", "green")
  .duration(150);
delay += 200;

svg
  .append("path")
  .transition()
  .delay(delay)
  .attr("d", blue)
  .attr("fill", "blue")
  .duration(150);
delay += 200;

svg
  .append("path")
  .transition()
  .delay(delay)
  .attr("d", violet)
  .attr("fill", "violet")
  .duration(150);
delay += 200;

